"""Этап 3, вторая волна: дополнительные разделы статей до ~1500 слов.
Темы подобраны так, чтобы не повторять ни другие статьи, ни товарные страницы."""

ADD2 = {
"skladometr-ili-nasypnoy-kub": ([
 ("Откуда взялся складометр", ["Складочный кубометр пришёл из лесного хозяйства, где дрова веками считали саженями. Кубическая сажень — поленница примерно 2,13 на 2,13 метра — была мерой дров в дореволюционной России, и до сих пор в старых книгах по печному делу расход указан именно в саженях. Одна кубическая сажень — около 9,7 складометра.",
   "С переходом на метрическую систему поленницу стали мерить кубическими метрами, но коэффициент пустотности остался: дрова в поленнице никогда не заполняют объём целиком. По действующему ГОСТу на дрова коэффициенты пересчёта складочной меры в плотную зависят от породы, длины и толщины поленьев и лежат в пределах 0,65-0,8."]),
 ("Что влияет на коэффициент пересчёта", ["Длина полена. Короткие поленья 25-30 сантиметров ложатся плотнее, чем полуметровые: у них меньше изгибов по длине. Поэтому складометр коротких дров содержит больше древесины.",
   "Толщина. Тонкие поленья заполняют объём плотнее, толстые — оставляют крупные пустоты в углах между ними. Но тонкие дрова быстрее прогорают, так что выигрыш по объёму не всегда выигрыш по теплу.",
   "Прямизна и сучки. Ровная берёза из ствола укладывается плотно, кривые поленья из вершин и сучковатые — рыхло. Смешанные дрова из разных частей дерева дают коэффициент ниже.",
   "Способ укладки. Аккуратная поленница вручную плотнее, чем дрова, сложенные наспех. Насыпь в кузове — самая рыхлая: поленья лежат как попало, и пустот почти половина."]),
 ("Типичные ошибки покупателя", ["Первая — сравнивать цену без меры. «Куб дров за 2000» ничего не говорит, пока не ясно, насыпной это куб или складометр. Всегда уточняйте.",
   "Вторая — считать кузов по паспорту машины. Объём кузова в документах указан для сыпучих грузов «с горкой» или для воды, а реальные борта могут быть ниже. Надёжнее измерить рулеткой.",
   "Третья — путать «машину» с объёмом. «ГАЗель дров» у одного продавца — 3 куба, у другого — 5, если наращены борта. Просите назвать объём в кубах.",
   "Четвёртая — забывать про длину полена. Складометр полуметровых дров и складометр 30-сантиметровых содержат разное количество древесины, хотя занимают одинаковый объём."]),
 ("Насыпной куб и вес: быстрая проверка", ["Если под рукой есть безмен или напольные весы, можно проверить честность объёма косвенно. Наберите в пластиковый ящик известного объёма, например 50 литров, дрова насыпью, взвесьте и пересчитайте на кубометр. Для берёзы естественной влажности насыпной куб весит 350-450 кг, для сухой — 250-330. Сильно меньший вес при сухих на вид дровах — повод присмотреться к содержимому кузова."]),
 ("Как мы считаем объём", ["Мы продаём дрова насыпными кубами по объёму кузова. Перед выгрузкой вы можете измерить кузов и посмотреть, как насыпаны дрова. Объём в заявке и в кузове совпадают — оплата после выгрузки."]),
 ], [("Сколько складометров в кубической сажени?","Около 9,7."),
     ("Почему складометр короткими дровами выгоднее?","Короткие поленья ложатся плотнее, древесины в том же объёме больше.")]),

"skolko-drov-nuzhno-na-zimu": ([
 ("Градусо-сутки: как считают профессионалы", ["Теплотехники считают отопление не по месяцам, а по градусо-суткам: разница между температурой в доме и на улице, умноженная на число дней сезона. Для Екатеринбурга при +20 в доме это около 5800-6000 градусо-суток, для Нижнего Тагила — 6200-6400, для Каменска-Уральского — около 5700. Значит, при одинаковом доме в Тагиле дров уйдёт примерно на 7-10% больше, чем в Екатеринбурге.",
   "Зная теплопотери дома на один градус разницы, расход можно посчитать точно. Но для частного дома достаточно ориентиров по площади и материалу стен с поправкой на свой опыт за прошлую зиму."]),
 ("Расход по материалу стен", ["Брус 150 мм без утепления — один из самых «прожорливых» вариантов: дом 100 м² берёт 25-30 насыпных кубов за сезон. Бревно 240 мм и больше — 20-24. Кирпич в два кирпича без утеплителя — 24-28. Газобетон 375 мм — 18-22. Каркас с 200 мм минваты — 12-16.",
   "Утепление чердачного перекрытия даёт самый быстрый эффект: через потолок уходит до 30% тепла. Пол над холодным подпольем — ещё 15-20%. Окна со старыми рамами — до 25%. Утеплив чердак и заменив окна, многие сокращают расход дров на треть за один сезон."]),
 ("Как вести учёт расхода", ["Простой способ узнать свой реальный расход — вести журнал. Отметьте в начале сезона размер поленницы, записывайте, когда начали новый ряд, и раз в месяц считайте, сколько ушло. Через сезон у вас будет точная цифра для своего дома, а не усреднённая.",
   "Полезно отмечать и температуру на улице: так видно, сколько дров уходит в мороз и сколько в оттепель, и проще планировать докупку."]),
 ("Как распределить дрова по сезону", ["Отопительный сезон на Урале — с конца сентября до середины мая. Октябрь и апрель — мягкие месяцы, на них уходит по 6-8% годового объёма. Ноябрь и март — по 10-12%. Декабрь, январь и февраль — по 17-20% каждый. Поэтому к Новому году должна остаться больше половины запаса, иначе в феврале придётся докупать.",
   "Самые сухие дрова держите на январь-февраль: в морозы важна максимальная теплоотдача. Чуть более влажные удобно сжигать в межсезонье, когда печь можно топить спокойно."]),
 ("Ошибки при расчёте", ["Считать по прошлой мягкой зиме. Если прошлый сезон был тёплым, этого объёма может не хватить в обычный год.",
   "Не учитывать баню и хозяйственные постройки. Они легко добавляют 5-10 кубов к расходу дома.",
   "Брать сырые дрова в сентябре. Такие дрова дают на треть меньше тепла, и расход фактически вырастает на ту же треть."]),
 ], [("Насколько больше дров нужно в Нижнем Тагиле, чем в Екатеринбурге?","Примерно на 7-10% при одинаковом доме."),
     ("Как уменьшить расход дров?","Утеплить чердачное перекрытие и пол, заменить старые окна, топить сухими дровами.")]),

"kakie-drova-luchshe-dlya-bani": ([
 ("Аромат: что даёт каждая порода", ["Берёза даёт лёгкий запах дёгтя — многим он нравится, это «запах русской бани». Ольха пахнет мягко и чуть сладковато, её дым используют для копчения. Липа даёт тонкий медовый аромат. Осина почти не пахнет. Можжевельник и вишню кладут по одному-два полена для аромата в конце топки. Хвойные пахнут смолой, но в парной это скорее запах гари, чем леса."]),
 ("Каменка и порода дров", ["Каменке нужен сильный продолжительный жар, чтобы камни прогрелись насквозь: только тогда пар будет мягким и лёгким. Берёза и дуб дают такой жар, осина и липа — нет: они прогорают быстро.",
   "Поэтому каменку прогревают берёзой 1,5-3 часа в зависимости от массы камней, а последнюю закладку делают ольхой или осиной. Если камни прогреты слабо, пар получается «тяжёлым» и влажным, и никакие дрова в конце топки этого не исправят."]),
 ("Сколько топить баню", ["Металлическая печь с небольшой каменкой прогревает парную за 1-1,5 часа. Кирпичная печь с закрытой каменкой — за 3-5 часов, но потом держит тепло всю ночь. Баня по-чёрному топится 3-4 часа, после чего её проветривают ещё час, пока не уйдёт дым.",
   "Не торопитесь париться, как только в парной стало жарко: воздух прогревается быстрее камней и стен. Дайте бане «выстояться» 30-40 минут после последней закладки."]),
 ("Растопка банной печи", ["Для растопки берут сухую берёзовую лучину, бересту или хвойную щепу. Бересту не кладут много: она даёт сажу. Химические жидкости для розжига в бане не используют — их запах впитывается в дерево парной.",
   "Растопку кладут на колосник, сверху — тонкие поленья «шалашом», потом толстые. Поддувало при розжиге открыто полностью."]),
 ("Как хранить дрова у бани", ["Удобно держать недельный запас в предбаннике или под навесом у входа: дрова прогреваются и подсыхают. Но не у самой печи — расстояние до топки должно быть не меньше метра. Основной запас — в поленнице на участке."]),
 ], [("Сколько времени топить баню?","Металлическую печь — 1-1,5 часа, кирпичную — 3-5 часов."),
     ("Чем растапливать банную печь?","Сухой берёзовой лучиной или хвойной щепой, без химических жидкостей.")]),

"vlazhnost-drov": ([
 ("Абсолютная и относительная влажность", ["Влажность древесины считают двумя способами. Относительная — доля воды от общего веса полена. Абсолютная — отношение веса воды к весу сухой древесины. Свежая берёза с относительной влажностью 50% имеет абсолютную влажность 100%: воды в ней столько же, сколько древесины.",
   "Бытовые влагомеры обычно показывают абсолютную влажность. Поэтому цифры на приборе и в справочнике могут не совпадать: всегда смотрите, какую влажность указывает источник."]),
 ("Как работает влагомер", ["Игольчатый влагомер измеряет сопротивление древесины между двумя иглами: чем больше воды, тем лучше дерево проводит ток. Мерить нужно на свежем расколе полена, а не на торце и не на коре: торец всегда суше середины. Иглы вгоняют поперёк волокон. Для точности делают 3-4 замера в разных поленьях.",
   "Бесконтактные влагомеры удобнее, но их показания зависят от плотности породы: прибор нужно настроить на нужную породу. Недорогой игольчатый прибор стоит как полкуба дров и окупается первой же покупкой."]),
 ("Как дрова набирают влагу обратно", ["Сухая древесина гигроскопична: она впитывает влагу из воздуха до равновесной влажности. Летом на Урале это 12-15%, осенью в дождливые недели — до 18-20%. Под навесом дрова держатся на этом уровне. Без навеса после пары дождей наружные поленья набирают 30% и больше, а снег, тающий на поленнице весной, промачивает её насквозь."]),
 ("Сколько стоит сырость", ["Посчитаем на примере. Насыпной куб берёзы влажностью 20% даёт около 1200 кВт·ч. Тот же куб влажностью 45% — около 750-800 кВт·ч. При цене 2500 рублей за куб киловатт-час сухих дров стоит около 2,1 рубля, сырых — больше 3. То есть сырые дрова по цене тепла дороже сухих, даже если стоили столько же."]),
 ("Камерная сушка: как это устроено", ["В сушильной камере дрова продувают горячим воздухом при 60-90 градусах 3-7 суток. Вода выходит быстро, древесина не успевает растрескаться сильно. Попутно погибают жуки и споры грибов. Камерные дрова удобны для каминов, саун и ресторанов, но для обычной печи переплата не нужна: дрова естественной сушки за год доходят до тех же 15-20%."]),
 ], [("Где мерить влажность полена?","На свежем расколе посередине, иглы поперёк волокон."),
     ("Набирают ли сухие дрова влагу?","Да, без навеса — до 30% и выше после нескольких дождей.")]),

"skolko-stoit-kub-drov": ([
 ("Из чего складывается цена куба", ["В цене дров несколько статей. Лесосека и заготовка: аренда леса или покупка древесины на корню, работа вальщиков, вывоз хлыстов. Распиловка и колка: станки-дровоколы, топливо, работа. Сушка, если дрова сухие. Хранение на складе. И доставка до покупателя.",
   "Самая изменчивая часть — топливо для техники: когда дорожает солярка, дрова дорожают вслед. Самая заметная для покупателя — доставка, потому что её платят отдельно."]),
 ("Почему у разных продавцов разные цены", ["Разница в мере — насыпной куб или складометр. Разница в составе — «берёзовые» дрова у кого-то чистая берёза, у кого-то наполовину осина. Разница во влажности — свежая древесина тяжелее и дешевле в заготовке. Разница в качестве колки и длине полена. И, наконец, разница в честности объёма.",
   "Поэтому сравнивать надо не цифру в объявлении, а цену за одинаковые дрова в одинаковой мере с одинаковой доставкой."]),
 ("Как цена зависит от объёма заказа", ["Цена куба почти не зависит от объёма: заготовка куба стоит одинаково. Но доставка распределяется на весь объём: одна поездка на 10 кубов дешевле в пересчёте на куб, чем поездка на 3 куба. Поэтому заказ на весь сезон одной машиной выходит дешевле нескольких маленьких."]),
 ("Как сэкономить на дровах", ["Покупать летом: дрова естественной влажности дешевле, к зиме высохнут. Брать полную машину или делить её с соседями. Покупать чурки и колоть самим. Брать смешанные вместо чистой берёзы для отопления. Топить сухими дровами: они дают больше тепла с каждого рубля. Утеплить дом — самый долгий, но самый выгодный способ сократить расходы."]),
 ("Сколько тратит на дрова семья", ["Дом 100 м² на дровах — 18-22 насыпных куба берёзы за сезон. По нашим ценам с доставкой это от %%sum.berezovye.18%% до %%sum.berezovye.22%% рублей за сезон — две машины. Баня при топке раз в неделю добавляет от %%sum.berezovye.4%% до %%sum.berezovye.7%% рублей в год. На смешанных дровах бюджет меньше на 15-20%."]),
 ], [("Сколько денег уходит на дрова за зиму?","Для дома 100 м² — около 41-51 тысячи рублей на берёзовых дровах плюс доставка."),
     ("Почему дрова у разных продавцов стоят по-разному?","Разная мера, порода, влажность, длина полена и честность объёма.")]),

"kakie-drova-luchshe-dlya-otopleniya": ([
 ("Лиственница и дуб: есть ли смысл", ["Лиственница — самая плотная хвойная порода на Урале, по теплу с куба близка к берёзе. Смолы в ней много, поэтому она стреляет и требует хорошей тяги. Дубовые дрова на Урале редкость: дуб здесь растёт мало, привозной стоит дорого. Для отопления дома переплачивать за дуб нет смысла — берёза даёт почти столько же тепла."]),
 ("Ясень, клён, тополь", ["Ясень и клён — плотные лиственные породы, горят хорошо, близко к берёзе. В уральских дровах они встречаются нечасто, обычно как примесь из городских вырубок. Тополь — самая лёгкая порода: тепла на треть меньше берёзы, дыма больше. Тополиные дрова дешёвые, но для отопления невыгодны."]),
 ("Как печь влияет на выбор", ["Кирпичная печь с большим теплоёмким массивом любит плотные породы: берёзу, дуб, лиственницу — им нужно долго прогревать кирпич. Металлическая печь греет быстро и быстро остывает, ей подходят любые сухие дрова, а хвойные позволяют быстро нагреть помещение. Твердотопливный котёл с водяным контуром — берёза и смешанные. Камин-печь со стеклом — сухая берёза, чтобы стекло не коптилось."]),
 ("Одна порода или смесь", ["Многие печники советуют смесь: хвойные для быстрого розжига, берёзу для основного жара, осину раз в несколько недель для чистки. Такая схема даёт ровное горение и не забивает дымоход. Если весь запас — чистая берёза, всё равно держите немного осины на сезон."]),
 ("Как проверить, что дрова греют хорошо", ["Хорошие дрова в исправной печи горят светло-жёлтым пламенем, дым из трубы почти прозрачный или белый. Тёмный густой дым — признак сырых дров или нехватки воздуха. Если печь дымит и плохо греет на любых дровах — проверьте дымоход и задвижку, а не породу."]),
 ], [("Есть ли смысл топить дом дубом?","На Урале нет: дуб дорогой, а берёза даёт почти столько же тепла."),
     ("Почему из трубы идёт чёрный дым?","Дрова сырые или печи не хватает воздуха.")]),

"skolko-vesit-kub-drov": ([
 ("Как вес меняется при сушке", ["За первые три месяца под навесом колотая берёза теряет больше всего воды — до половины лишней влаги. Насыпной куб, который весил 450 кг, к осени весит 330-350 кг. После года сушки — 280-310. Дальше вес почти не меняется: древесина приходит в равновесие с воздухом.",
   "Взвешивая контрольную охапку раз в месяц, можно следить, как сохнут дрова, без влагомера: когда вес перестаёт падать, дрова высохли."]),
 ("Вес горбыля, чурок и щепы", ["Чурки неколотые весят столько же на кубометр древесины, что и колотые, но в насыпном кузове лежат плотнее: насыпной куб берёзовых чурок — 380-500 кг в зависимости от влажности. Горбыль пиленый — 200-280 кг на насыпной куб. Щепа и обрезки — 150-250 кг."]),
 ("Вес брикетов и угля для сравнения", ["Топливные брикеты — около 1000-1200 кг на плотный кубометр, в упаковках на поддоне — 700-900 кг на кубометр поддона. Каменный уголь насыпью — 800-900 кг на кубометр. Пеллеты в мешках — около 650 кг на кубометр. Поэтому тонна брикетов или угля занимает в сарае гораздо меньше места, чем тонна дров."]),
 ("Как перевезти дрова самому", ["Легковой прицеп грузоподъёмностью 500-750 кг возьмёт 1,5-2 насыпных куба сухих дров или 1-1,5 куба сырых. Багажник универсала — около 0,3-0,5 куба. Перегруз прицепа опасен: ломается ось и ухудшается торможение. Поэтому большие объёмы выгоднее заказывать с доставкой."]),
 ("Вес в документах и на весах", ["Некоторые продавцы торгуют дровами на вес — тоннами. Это честно, только если известна влажность: тонна сырых дров содержит на треть меньше древесины, чем тонна сухих. Для покупателя надёжнее объёмная мера с осмотром дров."]),
 ], [("Сколько весит насыпной куб берёзовых чурок?","380-500 кг в зависимости от влажности."),
     ("Сколько дров везёт легковой прицеп?","1,5-2 насыпных куба сухих или 1-1,5 сырых.")]),

"teplota-sgoraniya-drov": ([
 ("Высшая и низшая теплота сгорания", ["В справочниках встречаются две цифры. Высшая теплота сгорания учитывает тепло, которое выделяется, когда водяной пар из дымовых газов конденсируется. Низшая — без него. В обычной печи пар уходит в трубу, поэтому для расчётов отопления берут низшую теплоту. Для сухой древесины разница между ними около 10%."]),
 ("Что такое зольность и почему она важна", ["Зольность — доля несгораемых минералов в топливе. У чистой древесины она 0,5-1%, у коры — 3-5%, у древесных брикетов — 0,5-1,5%, у каменного угля — 10-25%. Высокая зольность не только забивает колосник, но и уносит часть тепла: зола нагревается и выгребается горячей. Поэтому дрова с большим количеством коры дают меньше полезного тепла."]),
 ("Летучие вещества и пламя", ["Древесина на 75-85% состоит из летучих веществ: при нагреве они выходят газом и сгорают пламенем. Остальное — углерод, который тлеет в виде углей. Поэтому дрова горят длинным ярким пламенем, а уголь — короткими синими язычками. Длинное пламя хорошо прогревает дымооборот кирпичной печи, угли — дают долгий жар в топке."]),
 ("Как посчитать стоимость тепла", ["Разделите цену единицы топлива на её теплоту сгорания с учётом КПД. Насыпной куб берёзы за 2500 рублей, высушенной до 20%, даёт около 1200 кВт·ч, при КПД 70% — 840 кВт·ч в дом, это около 3 рублей за кВт·ч. Тонна брикетов за 11 000 рублей даёт 5000 кВт·ч, при КПД 75% — 3750 в дом, около 2,9 рубля. Уголь за 9500 рублей тонна, 6500 кВт·ч, КПД 70% — около 2,1 рубля. Это помогает выбрать топливо по цене, а не по рекламе."]),
 ("Влажность против породы", ["Сухая осина влажностью 15% даёт тепла больше, чем сырая берёза влажностью 45%. Это главный вывод из таблиц теплоты сгорания: правильная сушка важнее выбора породы. Плотная порода — бонус, сухость — обязательное условие."]),
 ], [("Чем высшая теплота сгорания отличается от низшей?","Высшая учитывает тепло конденсации пара из дыма; для печей берут низшую."),
     ("Как посчитать цену тепла?","Разделить цену топлива на теплоту сгорания и КПД печи.")]),

"drova-dlya-kotla-dlitelnogo-goreniya": ([
 ("Котлы верхнего горения и пиролизные", ["Котлы верхнего горения устроены как высокая шахта: дрова загружают доверху, поджигают сверху, и огонь медленно опускается вниз. Одна закладка горит 8-30 часов. Им подходят любые сухие дрова, а также брикеты.",
   "Пиролизные, или газогенераторные, котлы разделяют процесс на две камеры: в нижней дрова тлеют без доступа воздуха и выделяют газ, в верхней газ сгорает при высокой температуре. КПД таких котлов — 85-90%, но они самые требовательные к влажности: выше 20% пиролиз идёт плохо, котёл гаснет и зарастает смолой."]),
 ("Как правильно загружать котёл", ["Поленья укладывают плотно, вдоль топки, без больших пустот: так горение идёт ровно. Крупные поленья кладут вниз, мелкие — наверх для розжига. Не загружайте котёл свежими дровами прямо на горячие угли с закрытой заслонкой — дрова начнут выделять газ, который может вспыхнуть хлопком при открытии дверцы."]),
 ("Теплоаккумулятор: зачем он нужен", ["Теплоаккумулятор — бак с водой на 500-2000 литров, который накапливает тепло от котла. Котёл работает на полной мощности с максимальным КПД, а дом получает тепло из бака равномерно. С теплоаккумулятором котёл топят 1-2 раза в сутки, дров уходит на 15-25% меньше, а смолы почти нет: котёл не работает в режиме тления."]),
 ("Типичные проблемы и причины", ["Котёл гаснет ночью — дрова сырые или заслонка прикрыта слишком сильно. Смола течёт из дверцы — сырые дрова и низкая температура обратки. Котёл не набирает температуру — забит теплообменник или мала тяга. Расход дров вырос в полтора раза — проверьте влажность новой партии."]),
 ("Сколько дров уходит в котёл", ["Котёл длительного горения на сухой берёзе в доме 100 м² расходует 15-18 насыпных кубов за сезон — на 15-25% меньше, чем обычная печь. С теплоаккумулятором — ещё меньше. На сырых дровах экономии нет совсем: расход вырастает до уровня обычной печи и выше."]),
 ], [("Какой котёл самый требовательный к дровам?","Пиролизный: ему нужны дрова не влажнее 20%."),
     ("Зачем котлу теплоаккумулятор?","Котёл работает на полной мощности, дров уходит меньше, смолы почти нет.")]),

"skolko-gorbylya-v-kube": ([
 ("Горбыль деловой и дровяной", ["Деловой горбыль — ровный, толстый, с одной гладкой стороной: его берут на заборы, обрешётку, опалубку. Он дороже, продаётся пачками и длинномером. Дровяной горбыль — тонкий, кривой, с остатками коры, его пилят на куски и продают на топливо. Покупая горбыль для печи, деловой брать незачем: переплата за ровность."]),
 ("Хвойный и лиственный горбыль", ["На уральских пилорамах в основном пилят сосну и ель, поэтому горбыль почти всегда хвойный. Берёзовый появляется там, где пилят берёзу на мебельную заготовку или доску, — его меньше и он дороже. По теплу берёзовый горбыль заметно лучше, но и хвойный хорошо подходит для бани, летней кухни и растопки."]),
 ("Как хранить горбыль", ["Пиленый горбыль складывают так же, как дрова — в поленницу под навес. Длинный в пачках — на лаги поперёк, чтобы не касался земли, под крышей или накрыв сверху. Кора на горбыле держит влагу и привлекает короедов, поэтому горбыль не хранят годами: его сжигают в первый же сезон."]),
 ("Плюсы горбыля для дачи", ["Для дачи, где печь топят от случая к случаю, горбыль удобен: дешёвый, быстро разгорается, не надо колоть. Летом им топят баню и мангал, зимой — печь в сторожке или мастерской. А деловой горбыль идёт на хозяйственные нужды: грядки, заборы, временные навесы."]),
 ("Как пилить длинный горбыль", ["Пачку разрезают бензопилой сразу целиком, стянув её стропой или проволокой: так за полчаса можно распилить кубометр. Циркуляркой удобнее пилить поштучно. Длину куска выбирают под топку — обычно 30-50 сантиметров."]),
 ], [("Чем деловой горбыль отличается от дровяного?","Деловой ровный и толстый — для построек, дровяной тонкий и кривой — на топливо."),
     ("Как быстро распилить пачку горбыля?","Стянуть её и пилить бензопилой целиком.")]),

"hranenie-drov": ([
 ("Поленница-круг и другие формы", ["Кроме прямой поленницы вдоль стены, дрова складывают в круглые поленницы — «стога» или «хаусы». Внешний ряд поленьев кладут с наклоном внутрь, середину заполняют неровными поленьями, верх выкладывают корой наружу как крышу. Такая поленница устойчива, хорошо продувается и сама сбрасывает дождь. В диаметре 2-2,5 метра и высотой 2 метра она вмещает 6-8 складометров.",
   "Ещё одна форма — поленница между столбами: две вертикальные опоры по краям держат ряды, и не нужно выкладывать клетки на торцах."]),
 ("Дровник своими руками", ["Простейший дровник — каркас из бруса 100×100, крыша из профлиста или шифера с уклоном назад, пол из поддонов. Ширина 0,8-1 метр, длина — по объёму. На 15 складометров при высоте 1,8 метра и глубине 1 метр нужно около 8 метров длины. Задняя стенка — из досок с зазором 2-3 сантиметра, передняя — открыта."]),
 ("Пожарная безопасность", ["Поленницу не ставят вплотную к деревянному дому и не загораживают ею окна и выходы. Расстояние до печной трубы, бани и мангала — не меньше нескольких метров. В доме дрова держат не ближе метра от печи. Если дрова лежат у стены дома, между ними и стеной нужен промежуток для проветривания — иначе стена начнёт гнить."]),
 ("Хранение на балконе и в городе", ["Для камина в квартире или в городском доме дрова хранят в сухом подсобном помещении или на застеклённом балконе в коробах. Берут сухие дрова небольшими объёмами — 0,5-1 куб. Сырые дрова в квартире не хранят: влага и плесень."]),
 ("Как обновлять запас", ["Новые дрова кладите отдельно от старых, а старые сжигайте в первую очередь. Удобно держать две поленницы: одну на текущий сезон, другую — сохнущую на следующий. Так в печь всегда идут дрова, пролежавшие под навесом не меньше года."]),
 ], [("Как сложить круглую поленницу?","Внешний ряд с наклоном внутрь, середина — неровные поленья, верх корой наружу."),
     ("Какой дровник нужен на 15 складометров?","Около 8 метров длиной при высоте 1,8 и глубине 1 метр.")]),

"pochemu-drova-treshchat": ([
 ("Физика треска подробнее", ["Древесина состоит из клеток-трубочек, вытянутых вдоль ствола. В сырой древесине они заполнены водой и соками, в хвойной — ещё и смолой в смоляных ходах. При нагреве до 100 градусов вода закипает. Если пар может выйти через торцы, полено тихо шипит. Если пар заперт в клетках или сучке, давление растёт, пока стенка не лопнет — раздаётся щелчок. Смола кипит при более высокой температуре и даёт резкий хлопок."]),
 ("Почему сучки стреляют сильнее", ["Сучок — это основание ветки, вросшее в ствол. Древесина в нём плотнее, смолы больше, а волокна идут поперёк волокон ствола. Пару и газам из сучка труднее выйти, поэтому сучковатые поленья стреляют громче и чаще. Хвойные сучки особенно смолистые."]),
 ("Можно ли совсем убрать треск", ["Полностью — нет: любая древесина при горении немного потрескивает. Но сухие лиственные дрова без сучков горят почти бесшумно. Камерная сушка уменьшает треск сильнее естественной: вода удаляется равномернее. Некоторые любят треск и специально кладут в камин одно-два сосновых полена — но только в закрытую топку."]),
 ("Треск как подсказка", ["По звуку можно оценить дрова. Громкое шипение и пена на торцах — дрова сырые. Частые резкие хлопки — много смолы или сучков. Ровное тихое потрескивание — сухие лиственные дрова в нормальном режиме. Если в закрытой печи слышны глухие удары — это газы вспыхивают в топке из-за нехватки воздуха; откройте поддувало."]),
 ("Безопасность у открытого огня", ["Перед камином кладут негорючий предтопочный лист или плитку не меньше 50 сантиметров вперёд от топки. Каминный экран из сетки задерживает угольки. Ковры и мебель не ставят ближе метра. У костра и в уличной печи на даче стреляющие хвойные угли могут поджечь сухую траву — держите рядом воду."]),
 ], [("Почему сучковатые поленья стреляют сильнее?","В сучке больше смолы и плотная древесина, пару труднее выйти."),
     ("Что значат глухие хлопки в печи?","Газы вспыхивают из-за нехватки воздуха — откройте поддувало.")]),
}
